@page "/settings"
@using sv_98d3e72252454094875544eab7091e57.Services
@inject ISettingsService SettingsService
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-container">
    <nav class="settings-sidebar">
        <ul>
            <li class="@(ActiveSection == "Profile" ? "active" : "")" @onclick='() => SetSection("Profile")'>
                <span class="nav-icon">👤</span> Profile
            </li>
            <li class="@(ActiveSection == "Notifications" ? "active" : "")" @onclick='() => SetSection("Notifications")'>
                <span class="nav-icon">🔔</span> Notifications
            </li>
            <li class="@(ActiveSection == "Security" ? "active" : "")" @onclick='() => SetSection("Security")'>
                <span class="nav-icon">🔒</span> Security
            </li>
            <li class="@(ActiveSection == "Appearance" ? "active" : "")" @onclick='() => SetSection("Appearance")'>
                <span class="nav-icon">🎨</span> Appearance
            </li>
        </ul>
    </nav>

    <main class="settings-content">
        @if (!string.IsNullOrEmpty(ToastMessage))
        {
            <div class="toast @ToastType">
                @ToastMessage
                <button class="toast-close" @onclick="DismissToast">✕</button>
            </div>
        }

        @switch (ActiveSection)
        {
            case "Profile":
                <section class="settings-section">
                    <h2>Profile Settings</h2>
                    <div class="profile-form">
                        <div class="avatar-area">
                            <div class="avatar-preview">
                                <img src="@ProfileAvatarUrl" alt="Avatar" />
                            </div>
                            <label>Avatar URL</label>
                            <input type="text" @bind="ProfileAvatarUrl" />
                        </div>
                        <div class="form-group">
                            <label>Display Name</label>
                            <input type="text" @bind="ProfileDisplayName" />
                        </div>
                        <div class="form-group">
                            <label>Email</label>
                            <input type="email" @bind="ProfileEmail" />
                        </div>
                        <div class="form-group">
                            <label>Bio</label>
                            <textarea rows="4" @bind="ProfileBio"></textarea>
                        </div>
                        <div class="button-group">
                            <button class="btn-primary" @onclick="SaveProfile">Save Changes</button>
                            <button class="btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
                        </div>
                    </div>
                </section>
                break;

            case "Notifications":
                <section class="settings-section">
                    <h2>Notification Preferences</h2>
                    <div class="notifications-form">
                        <div class="toggle-group">
                            <label class="toggle-label">
                                <span>Email Notifications</span>
                                <label class="switch">
                                    <input type="checkbox" @bind="NotifEmail" />
                                    <span class="slider"></span>
                                </label>
                            </label>
                            <label class="toggle-label">
                                <span>Push Notifications</span>
                                <label class="switch">
                                    <input type="checkbox" @bind="NotifPush" />
                                    <span class="slider"></span>
                                </label>
                            </label>
                            <label class="toggle-label">
                                <span>Weekly Digest</span>
                                <label class="switch">
                                    <input type="checkbox" @bind="NotifWeeklyDigest" />
                                    <span class="slider"></span>
                                </label>
                            </label>
                        </div>
                        <div class="muted-channels">
                            <h3>Muted Channels</h3>
                            @foreach (var channel in AvailableChannels)
                            {
                                <label class="checkbox-label">
                                    <input type="checkbox" checked="@MutedChannels.Contains(channel)"
                                           @onchange="(e) => ToggleMutedChannel(channel, (bool)(e.Value ?? false))" />
                                    <span>@channel</span>
                                </label>
                            }
                        </div>
                        <div class="button-group">
                            <button class="btn-primary" @onclick="SaveNotifications">Save Preferences</button>
                        </div>
                    </div>
                </section>
                break;

            case "Security":
                <section class="settings-section">
                    <h2>Security Settings</h2>

                    <div class="security-panel">
                        <div class="expandable-panel">
                            <button class="panel-header" @onclick="TogglePasswordPanel">
                                <span>Change Password</span>
                                <span class="expand-icon">@(PasswordPanelExpanded ? "▼" : "▶")</span>
                            </button>
                            @if (PasswordPanelExpanded)
                            {
                                <div class="panel-body">
                                    <div class="form-group">
                                        <label>Current Password</label>
                                        <input type="password" @bind="CurrentPassword" />
                                    </div>
                                    <div class="form-group">
                                        <label>New Password</label>
                                        <input type="password" @bind="NewPassword" />
                                    </div>
                                    <div class="form-group">
                                        <label>Confirm Password</label>
                                        <input type="password" @bind="ConfirmPassword" />
                                    </div>
                                    <button class="btn-primary" @onclick="UpdatePassword">Update Password</button>
                                </div>
                            }
                        </div>

                        <div class="toggle-label">
                            <span>
                                Two-Factor Authentication
                                <span class="status-indicator @(TwoFactorEnabled ? "status-on" : "status-off")">
                                    @(TwoFactorEnabled ? "Enabled" : "Disabled")
                                </span>
                            </span>
                            <label class="switch">
                                <input type="checkbox" @bind="TwoFactorEnabled" />
                                <span class="slider"></span>
                            </label>
                        </div>

                        <div class="sessions-area">
                            <h3>Active Sessions</h3>
                            <table class="sessions-table">
                                <thead>
                                    <tr>
                                        <th>Device</th>
                                        <th>Location</th>
                                        <th>Last Active</th>
                                        <th></th>
                                    </tr>
                                </thead>
                                <tbody>
                                    @if (Sessions != null)
                                    {
                                        @foreach (var session in Sessions)
                                        {
                                            <tr>
                                                <td>@session.Device</td>
                                                <td>@session.Location</td>
                                                <td>@FormatLastActive(session.LastActive)</td>
                                                <td>
                                                    @if (session.Id != CurrentSessionId)
                                                    {
                                                        <button class="btn-danger-sm" @onclick="() => ConfirmRevokeSession(session)">Revoke</button>
                                                    }
                                                    else
                                                    {
                                                        <span class="current-badge">Current</span>
                                                    }
                                                </td>
                                            </tr>
                                        }
                                    }
                                </tbody>
                            </table>
                        </div>
                    </div>

                    @if (ShowRevokeConfirmation)
                    {
                        <div class="modal-overlay" @onclick="CancelRevoke">
                            <div class="modal" @onclick:stopPropagation="true">
                                <h3>Revoke Session</h3>
                                <p>Are you sure you want to revoke the session on <strong>@SessionToRevoke?.Device</strong> in <strong>@SessionToRevoke?.Location</strong>?</p>
                                <div class="button-group">
                                    <button class="btn-danger" @onclick="RevokeSession">Revoke</button>
                                    <button class="btn-secondary" @onclick="CancelRevoke">Cancel</button>
                                </div>
                            </div>
                        </div>
                    }
                </section>
                break;

            case "Appearance":
                <section class="settings-section">
                    <h2>Appearance Settings</h2>
                    <div class="appearance-form">
                        <div class="form-group">
                            <label><strong>Theme</strong></label>
                            <div class="radio-group">
                                <label class="radio-label">
                                    <input type="radio" name="theme" value="Light" @onchange='() => AppTheme = "Light"' checked="@(AppTheme == "Light")" /> Light
                                </label>
                                <label class="radio-label">
                                    <input type="radio" name="theme" value="Dark" @onchange='() => AppTheme = "Dark"' checked="@(AppTheme == "Dark")" /> Dark
                                </label>
                                <label class="radio-label">
                                    <input type="radio" name="theme" value="System" @onchange='() => AppTheme = "System"' checked="@(AppTheme == "System")" /> System
                                </label>
                            </div>
                        </div>
                        <div class="form-group">
                            <label><strong>Font Size</strong></label>
                            <div class="radio-group">
                                <label class="radio-label">
                                    <input type="radio" name="fontSize" value="Small" @onchange='() => AppFontSize = "Small"' checked="@(AppFontSize == "Small")" /> Small
                                </label>
                                <label class="radio-label">
                                    <input type="radio" name="fontSize" value="Medium" @onchange='() => AppFontSize = "Medium"' checked="@(AppFontSize == "Medium")" /> Medium
                                </label>
                                <label class="radio-label">
                                    <input type="radio" name="fontSize" value="Large" @onchange='() => AppFontSize = "Large"' checked="@(AppFontSize == "Large")" /> Large
                                </label>
                            </div>
                        </div>
                        <div class="form-group">
                            <label><strong>Language</strong></label>
                            <select @bind="AppLanguage">
                                <option value="English">English</option>
                                <option value="Spanish">Spanish</option>
                                <option value="French">French</option>
                                <option value="German">German</option>
                                <option value="Japanese">Japanese</option>
                            </select>
                        </div>
                        <div class="toggle-label">
                            <span><strong>Compact Mode</strong></span>
                            <label class="switch">
                                <input type="checkbox" @bind="AppCompactMode" />
                                <span class="slider"></span>
                            </label>
                        </div>

                        <div class="preview-area @GetPreviewClasses()">
                            <h4>Live Preview</h4>
                            <p>This is how your content will look with the selected settings.</p>
                            <div class="preview-card">
                                <strong>Sample Card</strong>
                                <p>Theme: @AppTheme | Font: @AppFontSize | Language: @AppLanguage</p>
                                <p>Compact mode is @(AppCompactMode ? "on" : "off").</p>
                            </div>
                        </div>

                        <div class="button-group">
                            <button class="btn-primary" @onclick="SaveAppearance">Save</button>
                        </div>
                    </div>
                </section>
                break;
        }
    </main>
</div>

